      mc: [
        { skill: "<strong>Paraphrase, not echo:</strong> in identity texts the right option usually rewords the text (\"felt out of place\" for \"was a fish out of water\"); the option that repeats the text's exact words often changes the meaning.", paper: "P2",
          q: "Text: \"Growing up between two cultures, Sami often felt he belonged fully to neither.\" Which statement is closest in meaning?", options: ["Sami belonged to both cultures equally.", "Sami did not feel completely at home in either culture.", "Sami grew up in two different countries.", "Sami rejected both cultures."], answer: 1, why: "\"belonged fully to neither\" = not completely at home in either; D is too strong, C is not stated." },
        { skill: "<strong>Tone words in 30 s:</strong> learn attitude adjectives (nostalgic, defensive, ambivalent, defiant, resigned) - Paper 2 often asks how a writer feels about their identity.", paper: "P2",
          q: "\"I used to cringe when my mother spoke Hindi in public; now I wish I'd paid more attention.\" The writer's present attitude is best described as:", options: ["defiant", "regretful", "indifferent", "amused"], answer: 1, why: "\"I wish I'd paid more attention\" expresses regret." },
        { skill: "<strong>Strong-word trap:</strong> eliminate options containing always / never / completely / all unless the text says so - writers on identity usually hedge (often, many, some).", paper: "P2" },
        { skill: "<strong>Theme vocabulary for Criterion A:</strong> have 8 ready words for Identities (heritage, assimilate, stereotype, self-esteem, belonging, peer pressure, well-being, subculture) and one complex sentence using two of them.", paper: "P1",
          q: "Which word best completes the sentence? \"Many second-generation immigrants feel pressure to ___ into the dominant culture.\"", options: ["assimilate", "associate", "accumulate", "accommodate"], answer: 0, why: "assimilate into a culture = become part of it; the others do not collocate with 'into the culture' in this sense." },
      ],
